import pytest
from candidate import flip_case


def test_flip_case_mixed_case_string():
    assert flip_case('Hello') == 'hELLO'


def test_flip_case_all_lowercase():
    assert flip_case('hello') == 'HELLO'


def test_flip_case_all_uppercase():
    assert flip_case('HELLO') == 'hello'


def test_flip_case_empty_string():
    assert flip_case('') == ''


def test_flip_case_single_lowercase_char():
    assert flip_case('a') == 'A'


def test_flip_case_single_uppercase_char():
    assert flip_case('A') == 'a'


def test_flip_case_single_z_lowercase():
    assert flip_case('z') == 'Z'


def test_flip_case_single_z_uppercase():
    assert flip_case('Z') == 'z'


def test_flip_case_special_characters_unchanged():
    assert flip_case('123!@#$%^&*()') == '123!@#$%^&*()'


def test_flip_case_numbers_unchanged():
    assert flip_case('12345') == '12345'


def test_flip_case_mixed_alphanumeric():
    assert flip_case('aB1cD2') == 'Ab1Cd2'


def test_flip_case_whitespace_only():
    assert flip_case('   ') == '   '


def test_flip_case_tabs_and_newlines():
    assert flip_case('\t\n') == '\t\n'


def test_flip_case_unicode_lowercase():
    assert flip_case('héllo') == 'HÉLLO'


def test_flip_case_unicode_uppercase():
    assert flip_case('HÉLLO') == 'héllo'


def test_flip_case_emoji_and_letters():
    assert flip_case('h🐱i') == 'H🐱I'


def test_flip_case_long_string():
    s = 'a' * 1000
    assert flip_case(s) == 'A' * 1000


def test_flip_case_none_input_raises_type_error():
    with pytest.raises(TypeError):
        flip_case(None)


def test_flip_case_integer_input_raises_type_error():
    with pytest.raises(TypeError):
        flip_case(123)


def test_flip_case_list_input_raises_type_error():
    with pytest.raises(TypeError):
        flip_case(['a', 'b'])


def test_flip_case_float_input_raises_type_error():
    with pytest.raises(TypeError):
        flip_case(3.14)


def test_flip_case_boolean_input_raises_type_error():
    with pytest.raises(TypeError):
        flip_case(True)


def test_flip_case_dict_input_raises_type_error():
    with pytest.raises(TypeError):
        flip_case({'a': 1})


def test_flip_case_return_type_is_string():
    result = flip_case('Hello')
    assert isinstance(result, str)


def test_flip_case_idempotent_on_numbers_only():
    assert flip_case('999') == '999'


def test_flip_case_idempotent_on_special_chars_only():
    assert flip_case('!!@@##') == '!!@@##'
